# Kaggle entry point (generated by submission/build.py).
import os
import sys
import time
import traceback

BASE = "/kaggle_simulations/agent"
if not os.path.exists(os.path.join(BASE, "weights.pt")):
    BASE = os.path.dirname(os.path.abspath(__file__))
while BASE in sys.path:
    sys.path.remove(BASE)
sys.path.insert(0, BASE)

import torch  # noqa: E402

torch.set_num_threads(1)
from ptcgnet.model import load_model  # noqa: E402
from ptcgnet.mcts import MCTSAgent, DeckLibrary  # noqa: E402
from ptcgnet.agents import net_eval, policy_choice, is_deck_request  # noqa: E402

CONFIG = __CONFIG__
DECK = [int(x) for x in open(os.path.join(BASE, "deck.csv")).read().split()]
MODEL = load_model(os.path.join(BASE, "weights.pt"), "cpu")
AGENT = MCTSAgent(MODEL, DECK, library=DeckLibrary(os.path.join(BASE, "decks")), **CONFIG)
LOG_ERRORS = []


def _fallback(obs):
    try:
        sel = obs["select"]
        p, v, c, _, _ = net_eval(MODEL, [obs])[0]
        return policy_choice(obs, p, c, greedy=True)
    except Exception:
        sel = obs.get("select") or {}
        k = int(sel.get("minCount", 0) or 0)
        return list(range(k))


def agent(obs, config=None):
    if is_deck_request(obs):
        return list(DECK)
    try:
        return [int(x) for x in AGENT.act(obs)]
    except Exception:
        if len(LOG_ERRORS) < 20:
            LOG_ERRORS.append(traceback.format_exc())
            print("AGENT ERROR", LOG_ERRORS[-1], file=sys.stderr, flush=True)
        return _fallback(obs)
